// A short selection from the existing25-card pool, not new missions or grading.
const box=(title,text)=>`<section><h2>${title}</h2>${text}</section>`;
const lines=(n=3)=>'<div class="writing" style="height:'+n*10+'mm"></div>';
const scheduleA='<table><tr><th>Minuten</th><th>Geplante Tätigkeit</th></tr><tr><td>10</td><td>Leitfrage und erste Vermutungen</td></tr><tr><td>10</td><td>Werkzeugprobe und Belegregeln</td></tr><tr><td>25</td><td>Drei Funde an zwei Standorten untersuchen</td></tr><tr><td>20</td><td>Merkmale vergleichen, Bestimmung begründen</td></tr><tr><td>15</td><td>Sichern und auf Naturmaterial/Fotofall übertragen</td></tr><tr><td>10</td><td>Puffer, Datei sichern, offene Fragen</td></tr></table>';
const scheduleB='<table><tr><th>Minuten</th><th>Geplante Tätigkeit</th></tr><tr><td>10</td><td>Leitfrage, Nische und Modellbedingungen</td></tr><tr><td>10</td><td>Bedienwege und Vergleich planen</td></tr><tr><td>20</td><td>Zwei ausgewählte Küstenvögel vergleichen</td></tr><tr><td>15</td><td>K3-Teil: dieselbe Muschel bei zwei Tidenständen</td></tr><tr><td>20</td><td>Vergleichsprodukt und alternative Deutungen</td></tr><tr><td>10</td><td>Sicherung und Naturtransfer</td></tr><tr><td>5</td><td>Puffer und Export</td></tr></table>';
const teacher=[
 box('START IM UNTERRICHT · 1 / 2',`<p><strong>Ranger Kompakt V1 · begleitete Erprobung, keine automatische Benotung.</strong> Zwei ausgewählte Einstiege aus K1–K5 und dem vorhandenen 25-Karten-Pool. Alle Zeitangaben sind ungeprüfte Planungswerte. Nicht alle Karten oder Vertiefungen in 90 Minuten bearbeiten.</p>
 <h3>Vorbereitung</h3><ul><li>Den exakt versionierten Kandidaten am tatsächlichen Gerät prüfen: System-/Browserversion eintragen, WebGL, Touch/Tastatur, Rotation, Dateiexport/-import, Hintergrund und 20 reale Minuten. Kein ungeprüftes iPad-Profil als freigegeben behandeln.</li><li>Schülerpfad A oder B auswählen, Naturmaterial beziehungsweise einen geeigneten Fotofall vorbereiten. Vollständiger Pool bleibt im Lernpaket.</li><li>Vorwissen A: Art, Merkmal, Standort und Beleg. Vorwissen B: Nahrung, Nische, Einflussfaktor, kontrollierter Vergleich und Tide.</li></ul>
 <h3>Optionale Werkzeugprobe · im jeweiligen 10-Minuten-Block</h3><p>Starttafel am Waldstart oder Menü „Startanleitung“ öffnen. Mit WASD/Steuerkreis gehen, auf der Landschaft ziehen, Fernglas für Tiere/Lupe für Pflanzen. Dasselbe sichtbare Individuum ruhig beobachten, Beleg sichern und eigene Notiz ergänzen. Pause, Export und Rückkehr kurz erproben. Keine neue Pflicht-Tutorialmission.</p>
 <h3>Pfad A · Wie sicher ist unsere Artenliste?</h3><p><strong>Ziel:</strong> Drei Bestimmungsfunde von zwei Orten mit beobachteten Merkmalen belegen; begründete Unsicherheit zulassen und eine Aussage übertragen. Anknüpfung: K1, C04/C05/C25; andere Karten nur bei Bedarf.</p>${scheduleA}
 <p><strong>Bedienweg:</strong> „Freie Erkundung“ → K1. An zwei unterschiedlichen Waldorten „Ort untersuchen“ nutzen, anonyme Funde und deren vergrößerte Merkmale prüfen; nicht vom eingeblendeten Programmnamen auf eigene Bestimmung schließen. Drei Fundzeilen und eine Begründung sichern. Anschließend unbekannten Eichen-Zweig beziehungsweise Naturmaterial/Fotofall vergleichen.</p>
 <p><strong>Produkt:</strong> eine Belegtabelle und eine vorläufige, begründete Artenliste. Erstentwurf und begründete Revision sichtbar aufbewahren.</p>`),
 box('START IM UNTERRICHT · 2 / 2',`<h3>Pfad B · Warum nutzen Küstenvögel denselben Raum unterschiedlich?</h3><p><strong>Ziel:</strong> Bei zwei ausgewählten Vogelarten Ressource, Suchweise und Standort/Tide vergleichen; K3-Teil unter gleichen Bedingungen auswerten. Anknüpfung: C03/C14 und K3. Quantitative eA-Stichproben C06, Populations-/Stoffmodelle und weitere Arten sind Vertiefung/Folgestunde.</p>${scheduleB}
 <p><strong>Bedienweg:</strong> Zum Küstenort gehen → „Ort untersuchen“; zwei Nahrungssuchvorgänge unbeschleunigt vergleichen. Die Detailansicht zeigt denselben Modellvorgang, vergibt selbst keinen Beleg. K3: Wattprobe öffnen, dieselbe konkrete Muschel, Probenstelle und Tiefe beibehalten; beschriftete Tidenzeitpunkte in Reihenfolge wählen und Beobachtungen sichern. Modellschritte sind keine Sichtungszeit.</p>
 <p><strong>Produkt:</strong> Nahrung × Suchweise × Standort/Tide, Muschelvergleich und eine Aussagegrenze. Erschöpfte Beute: Ein neues lokales Fenster beginnt einen <em>neuen Modellversuch</em>, kein Wiederbeleben realer Tiere und keine Fortsetzung einer Langzeitmessung. Alte Belege bleiben; Kontexte trennen.</p>
 <h3>Hilfen und fachliche Rückmeldung</h3><p>1: Beobachtbares Merkmal/konkreten Vorgang suchen lassen. 2: passende Tabelle oder Vergleichskriterium anbieten. 3: Quellen-/Lösungshinweis geben und dessen Nutzung kenntlich machen. Unterstützung ist keine unabhängige Leistung.</p>
 <p><strong>Erwartungen und Alternativen:</strong> A: Merkmalskombination oder „noch nicht sicher“ mit fehlendem Merkmal. B: passende Beute/äußere Technik; K3 mit identischer Muschel und kontrollierten Bedingungen. Beobachtung, Quelle und Deutung trennen; andere belegte Formulierungen zulassen.</p>
 <p><strong>Fehler unterscheiden:</strong> Falsche Deutung → Beleg/Kriterium erneut prüfen; unsichere Bestimmung → fehlendes Merkmal benennen; fehlender Beleg → dasselbe Individuum erneut beobachten; Speicherfehler → Originalexport sichern und technische Meldung bearbeiten. „Struktur vollständig“ heißt weder verstanden noch benotet.</p>
 <p><strong>Sicherung/Transfer:</strong> Erst- und Revisionsprodukt vergleichen; eine Aussage an Naturmaterial/Fotofall prüfen und eine Modellgrenze nennen. Das Nahrungsnetz ist ein Ausschnitt; Atmung/Stoffflüsse sind nicht einfach Nahrungskanten. Zeigerwerte sind keine aktuellen Messwerte, Tide keine Jahresfluthäufigkeit, sichtbare Tiere keine geschlossene Population.</p>
 <p><strong>Pilot:</strong> Verständlichkeit, Such-/Lesezeit, Hilfen, Fehlvorstellungen, Erst-/Revisionsprodukte und Naturtransfer anonym erfassen. Keine Wirksamkeits- oder Gerätefreigabe aus Formularabschlüssen ableiten.</p>`)
];
const pathA=[
 box('Pfad A · Wie sicher ist unsere Artenliste? · 1 / 2',`<p><strong>Leitfrage:</strong> Wie sicher können wir drei Funde von zwei Standorten bestimmen? Vorwissen: Art, Merkmal, Standort, Beobachtungsbeleg. Ziel: eine überprüfbare, vorläufige Artenliste.</p><p>90-Minuten-Planungsbeispiel: 10 Frage / 10 Vorbereitung / 25 Erkundung / 20 Vergleich / 15 Sicherung und Transfer / 10 Puffer. Keine gemessenen Schülerzeiten.</p><ol><li>Bei Bedarf Werkzeugprobe: Starttafel/Startanleitung öffnen; Lupe/Fernglas, Beleg und Export erproben.</li><li>„Freie Erkundung“ → K1 wählen. An zwei Waldorten „Ort untersuchen“ öffnen. Drei anonyme Funde in Nahansichten prüfen und jeweils selbst sichern. Eine Auswahl allein ist kein Fund.</li><li>Merkmale vor dem Bestimmungsnamen notieren. Bestimmung begründen oder bewusst unsicher lassen. Ein vorgegebener Artname ist noch keine eigene Bestimmung.</li></ol>
 <table><tr><th>Fund / Ort / Beleg</th><th>Beobachtete Merkmale</th><th>Vorläufige Bestimmung / Sicherheit</th></tr>${[1,2,3].map(i=>`<tr class="response"><td>Fund ${i}<br>Ort:<br>Beleg:</td><td></td><td></td></tr>`).join('')}</table>
 <h3>Meine erste Aussage</h3><p>Welche Merkmalskombination trägt deine Liste? Wo fehlt ein Merkmal?</p>${lines(3)}<p><strong>Hilfe:</strong> Erst ein sichtbares Merkmal beschreiben; dann eine Merkmalskombination vergleichen; erst danach Bestimmung oder Quelle nutzen.</p>`),
 box('Pfad A · Prüfen, revidieren, übertragen · 2 / 2',`<h3>Vergleich und begründete Revision</h3><p>Vergleicht zwei Fundzeilen. Trennt eigene Beobachtung, Quelleninformation und Deutung. Welche Änderung an der ersten Aussage ist nötig? „Noch nicht sicher, weil …“ ist eine begründbare Antwort.</p>${lines(5)}<h3>Transfer</h3><p>Vergleiche den unbekannten Eichen-Zweig oder ein von der Lehrkraft gegebenes Naturmaterial/einen Fotofall. Welches Bestimmungsprinzip lässt sich übertragen? Welches zusätzliche Merkmal brauchst du?</p>${lines(5)}<h3>Abgabe und Sicherung</h3><p>Abgeben: Belegtabelle, Erst- und Revisionsaussage, ein Transfersatz und eine Modellgrenze. Feldbuch öffnen → JSON exportieren. Keine Namen oder echten Schülerdaten in öffentliche Dateien übernehmen.</p><p><strong>Erwartbar:</strong> begründete Merkmalskombination oder ausdrücklich benannte Unsicherheit; alternative passende Deutungen sind zulässig. Die Lehrkraft bespricht die Erklärung. Eine vollständige Strukturprüfung ist keine Note.</p><p><strong>Falls etwas fehlt:</strong> fehlender Beleg → erneut ruhig dasselbe Individuum beobachten; unsicher → fehlendes Merkmal notieren; Speicherfehler → Original sichern und technische Meldung lesen. Der vollständige Materialpool und die K1-Hilfen bleiben verfügbar.</p>`)
];
const pathB=[
 box('Pfad B · Küstenvögel im selben Raum · 1 / 2',`<p><strong>Leitfrage:</strong> Warum nutzen Küstenvögel denselben Raum unterschiedlich? Vorwissen: Nahrung, Nische, Tide, Einflussfaktor und kontrollierter Vergleich. Ziel: einen belegten Vergleich erstellen und seine Reichweite begrenzen.</p><p>90-Minuten-Planungsbeispiel: 10 Frage / 10 Vorbereitung / 20 Vögel / 15 K3-Teil / 20 Auswertung / 10 Transfer / 5 Puffer. Vertiefungen sind optional, keine gemessenen Schülerzeiten.</p><ol><li>Zum Küstenort gehen, „Ort untersuchen“ öffnen. Zwei passende Vogelarten auswählen. Suchweise, konkrete Ressource und Aufnahme im unbeschleunigten Modelllauf ansehen.</li><li>Bei Bedarf „Detailvergrößerung“ nutzen. Gleicher Modellvorgang, kein Naturmaßstab und keine zusätzliche eigene Sichtung. In der Fläche scrollen; schließen und für die nächste Folge neu öffnen.</li><li>Beleg nur bei freier Weltsicht sichern. Datum/Modellfenster, Standort und Beobachtungsbedingungen dokumentieren. Bereits erschöpfte Beute erfordert einen ausdrücklich neuen Modellversuch; alte Belege nicht als seine Vorgänge ausgeben.</li></ol>
 <table><tr><th>Art / Beleg / Fenster</th><th>Ressource und Suchweise</th><th>Standort/Tide / äußere Aufnahme</th></tr><tr class="response"><td>Vogel 1:</td><td></td><td></td></tr><tr class="response"><td>Vogel 2:</td><td></td><td></td></tr></table><h3>Erster Vergleich</h3>${lines(4)}<p><strong>Hilfen:</strong> 1 konkrete Beute/Suchbewegung beschreiben; 2 Vergleichstabelle nutzen; 3 passenden Quellenhinweis lesen und als Hilfe kennzeichnen. Nicht alle vier Arten sind in dieser Doppelstunde Pflicht.</p>`),
 box('Pfad B · Kontrollierter K3-Teil und Aussagegrenzen · 2 / 2',`<ol><li>Wattprobe öffnen. Dieselbe konkrete Muschel, Probenstelle und Untersuchungstiefe für beide Tidenbeobachtungen beibehalten.</li><li>Beschriftete Niedrig-/Hochwasserzeitpunkte in zeitlicher Reihenfolge einstellen. Jeweils Beobachtung sichern. Modellzeit und aktive Beobachtungszeit unterscheiden.</li><li>Kein Wechsel des Rundgangs/Modellfensters zwischen den beiden Vergleichsbelegen. Abweichungen oder fehlende Kontrolle benennen, nicht still ergänzen.</li></ol><table><tr><th>Bedingung / Beleg</th><th>Dasselbe Individuum / Stelle / Tiefe</th><th>Beobachtung / Modellzeit</th></tr><tr class="response"><td>Niedrigwasser:</td><td></td><td></td></tr><tr class="response"><td>Hochwasser:</td><td></td><td></td></tr></table><h3>Unser Vergleichsprodukt</h3><p>Führe Vogelvergleich und Muschelteil zusammen. Welche Aussage tragen die Belege, welche alternative Erklärung bleibt möglich?</p>${lines(4)}<h3>Modellkritik und Transfer</h3><p>Eine gestaltete Regel ist kein unabhängiger Naturbeweis. Was müsste eine reale Untersuchung kontrollieren/messen? Vergleiche einen Natur-/Fotofall; nenne eine übertragbare Methode und eine Grenze.</p>${lines(3)}<p><strong>Abgabe:</strong> Tabellen, Erst-/Revisionsaussage und ein Transfersatz. JSON exportieren. Quantitative eA-Stichproben nur als angekündigte Vertiefung/Folgestunde. Eine vollständige Belegstruktur ist keine automatische Note; begründete alternative Deutungen fachlich besprechen.</p>`)
];
export const CLASSROOM_DOCUMENTS=Object.freeze({teacher:{file:'START-IM-UNTERRICHT',pages:teacher},'path-a':{file:'PFAD-A-Artenliste',pages:pathA},'path-b':{file:'PFAD-B-Kuestenvoegel',pages:pathB}});
export function renderStarterDocument(kind){
 const doc=CLASSROOM_DOCUMENTS[kind];if(!doc)throw Error('Unbekannter Unterrichtspfad.');
 return `<!doctype html><html lang="de"><meta charset="utf-8"><title>Ranger Kompakt · ${doc.file}</title><style>@page{size:A4;margin:15mm}*{box-sizing:border-box}body{font:13px/1.4 system-ui,sans-serif;color:#233a2e;max-width:180mm;margin:auto}h2{font:23px Georgia;margin:4mm 0}h3{font-size:15px;margin:4mm 0 1mm}p,ul,ol{margin:2.5mm 0}li{margin:1.5mm 0}table{border-collapse:collapse;width:100%;font-size:12px;margin:3mm 0}td,th{border:1px solid #87998c;padding:2mm;text-align:left}tr{break-inside:avoid}.response td{height:25mm}.writing{border:1px solid #87998c;background:repeating-linear-gradient(white,white 9mm,#c5d0c7 9.3mm,white 9.5mm);margin:2mm 0}section{break-before:page}section:first-child{break-before:auto}footer{font-size:11px;margin-top:3mm;border-top:1px solid #87998c}@media screen{body{padding:20px;background:#faf8ed}section{margin:20px 0 40px}}</style><body>${doc.pages.map(p=>p.replace('</section>','<footer>Ranger Kompakt · V1-Planungsbeispiel · begleitete Erprobung und menschliche Rückmeldung; keine gemessene Lernwirksamkeit.</footer></section>')).join('')}</body></html>`;
}
